// custom dark variables
@use "./dark.scss";

// size h -> height, w -> width
:root {
  --h-header: 56px;
  --h-logo: var(--h-header);
  --h-footer: 30px;

  --w-aside: 220px;
  --w-aside-collapsed: 64px;

  --radius: 4px;
  --radius-2: 8px;
}

// border
:root {
  --style-border: 1px solid var(--el-border-color);
}

@for $i from 0 through 30 {
  .p#{$i} { padding: 1px * $i; }
  .pt#{$i} { padding-top: 1px * $i; }
  .pr#{$i} { padding-right: 1px * $i; }
  .pb#{$i} { padding-bottom: 1px * $i; }
  .pl#{$i} { padding-left: 1px * $i; }

  .m#{$i} { margin: 1px * $i; }
  .mt#{$i} { margin-top: 1px * $i; }
  .mr#{$i} { margin-right: 1px * $i; }
  .mb#{$i} { margin-bottom: 1px * $i; }
  .ml#{$i} { margin-left: 1px * $i; }

  .lh#{$i} { line-height: 1px * $i; }
}

// import dark mode scss
 @use 'element-plus/theme-chalk/src/dark/css-vars.scss' as *;
@use './base.scss' as *;
@use './nprogress.scss' as *;
@use './transition.scss' as *;
@use './reset.scss' as *;
//@use './customize/dark.scss' as *;

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  // font-weight: normal;
}

body {
  min-height: 100vh;
  color: var(--el-text-color);
  transition: color 0.5s, background-color 0.5s;
  line-height: 1.6;
  font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu,
    Cantarell, 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
  font-size: 15px;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html,
body,
#app {
  height: 100%;
}

.fw {
  width: 100%;
}

.fh {
  height: 100%;
}

.tc {
  text-align: center;
}

.tr {
  text-align: right;
}

.fl {
  float: left;
}

.fr {
  float: right;
}

.pointer {
  cursor: pointer;
}

.flex {
  display: flex;
}

.flex-vertical {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.fill {
  flex: 1;
}

.jc-between {
  justify-content: space-between;
}

.ai-center {
  align-items: center;
}

.page-wrapper {
  width: 100%;
  height: 100%;
}

.relative {
  position: relative;
}

.absolute {
  position: absolute;
}

.widget-wrapper {
  height: var(--h-header);
  display: flex;
  align-items: center;
  cursor: pointer;

  .el-dropdown-link:focus {
    outline: none;
  }
}

.app-container {
  background-color: var(--el-bg-color);
  padding: 15px;
}

.app-wrapper {
  width: 100%;
  height: 100%;
  position: relative;

  .el-container {
    height: 100%;
    position: relative;
    .bg-img {
      position: absolute;
      left: 0;
      right: 0;
      width: 100%;
      height: 100%;
      background-repeat: no-repeat;
      background-size: cover;
    }
    :deep(.el-header) {
      padding: 0;
      height: auto;

      .header-wrapper {
        padding: 0 15px;
        height: var(--h-header);
        display: flex;
        align-items: center;
        justify-content: space-between;
        border-bottom: var(--style-border);
      }

      .tags-view-wrapper {
        // padding: 0 20px;
        border-bottom: var(--style-border);
        height: var(--height-tags-view);
      }
    }

    .el-main {
      padding: 0px;
      box-sizing: border-box;
      overflow-x: hidden;
      background-color: var(--el-bg-color-page);
    }

    .el-footer {
      height: var(--h-footer);
      line-height: var(--h-footer);
      font-size: 10px;
      color: var(--el-text-color-secondary);
      text-align: center;
      padding: 0 20px;
      position: relative;

      &::before {
        content: '';
        width: 100%;
        position: absolute;
        left: 0;
        top: 0;
        border-top: var(--style-border);
      }
    }
  }
}

.app-wrapper.app-vertical {
  .el-aside {
    width: var(--w-aside);
    position: relative;
    transition: width 0.28s;
    border-right: var(--style-border);

    &.aside-collapsed {
      width: var(--w-aside-collapsed);
    }
  }
}

@mixin truncated {
  display: inline-block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.el-scrollbar {
  height: 100%;
  width: 100%;
}

.el-scrollbar.has-header {
  height: 100%;
  width: 100%;
}

.el-scrollbar.has-logo {
  height: calc(100% - var(--h-logo)) !important;
}

:deep(.app-menu) {
  border-right: 0;
  background-color: transparent;
  width: 100%;

  .el-menu-item {
    color: var(--el-text-color-regular);

    .is-truncated {
      @include truncated;
    }

    &:hover {
      background-color: transparent;
    }
  }

  .el-menu-item.is-active {
    background-color: transparent;
    color: var(--el-color-primary);
  }

  .el-sub-menu {

    .el-sub-menu__title {
      color: var(--el-text-color-regular);
      .is-truncated {
        @include truncated;
      }

      &:hover {
        background-color: transparent;
      }
    }
    .el-menu {
      background-color: transparent;

      .el-menu-item, .el-sub-menu__title {
        text-indent: 9px;

        .is-truncated {
          @include truncated;
        }
      }
    }
  }

  &.app-menu__collapsed {
    padding: 0;

    .el-sub-menu.is-active {

      .el-icon {
        color: var(--el-color-primary);
      }
    }
  }
}

/* nprogress样式 */
#nprogress .bar {
  background: var(--el-color-primary) !important;
}

#nprogress .spinner-icon {
  border-top-color: var(--el-color-primary) !important;
  border-left-color: var(--el-color-primary) !important;
}

#nprogress .peg {
  box-shadow:
    0 0 10px var(--el-color-primary),
    0 0 5px var(--el-color-primary) !important;
}

// 用于重置element-plus组件库的原生样式

// 清除el-drawer header的margin-bottom
.el-drawer {
  .el-drawer__header {
    margin-bottom: 0;
  }
}

// 清除水平表单的margin-bottom
.el-form.clear-mb {
  .el-form-item {
    margin-bottom: 0;
  }
}

/* fade-transform */
.fade-transform-leave-active, .fade-transform-enter-active {
	transition: all 0.2s;
}

.fade-transform-enter-from {
	opacity: 0;
	transition: all 0.2s;
	transform: translateX(-10px);
}

.fade-transform-leave-to {
	opacity: 0;
	transition: all 0.2s;
	transform: translateX(10px);
}

